typedef struct case_spec {const char*name,*address,*hostname,*root,*cert,*key;pst_u16 port;int fail,echo;} case_spec;
static int creates,destroys,setups,cleanups;
static unsigned char*load(const char*p,pst_size*n){FILE*f;long z;unsigned char*b;*n=0;f=fopen(p,"rb");if(!f)return NULL;if(fseek(f,0,SEEK_END)||(z=ftell(f))<0||fseek(f,0,SEEK_SET)){fclose(f);return NULL;}b=(unsigned char*)malloc((size_t)z);if(!b){fclose(f);return NULL;}if(z&&fread(b,1,(size_t)z,f)!=(size_t)z){free(b);fclose(f);return NULL;}fclose(f);*n=(pst_size)z;return b;}
static int connect4(const char*a,pst_u16 p,SOCKET*out){SOCKET s;struct sockaddr_in x;memset(&x,0,sizeof(x));x.sin_family=AF_INET;x.sin_port=htons(p);x.sin_addr.s_addr=inet_addr(a);s=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);if(s==INVALID_SOCKET)return 0;if(connect(s,(struct sockaddr*)&x,sizeof(x))==SOCKET_ERROR){closesocket(s);return 0;}*out=s;return 1;}
static int waitone(pst_connection*c){PST_WAIT_RESULT w;memset(&w,0,sizeof(w));return pst_connection_wait(c,1000,&w)==PST_RESULT_OK&&!w.timed_out&&w.ready_interest;}
