s[0].name="B1";s[0].address=av[1];s[0].port=(pst_u16)atoi(av[2]);s[0].hostname="localhost";s[0].root=av[8];s[0].cert=av[9];s[0].key=av[10];s[0].fail=0;s[0].echo=1;s[1]=s[0];s[1].name="C";s[1].port=(pst_u16)atoi(av[3]);s[1].cert=av[11];s[1].key=av[12];s[1].fail=1;s[1].echo=1;s[2]=s[0];s[2].name="A";s[2].address=av[5];s[2].port=(pst_u16)atoi(av[6]);s[2].hostname=av[7];s[2].root=NULL;s[2].cert=NULL;s[2].key=NULL;s[2].fail=0;s[2].echo=0;s[3]=s[0];s[3].name="B2";s[3].port=(pst_u16)atoi(av[4]);memset(&snap,0,sizeof(snap));for(i=0;i<4;i++)if(!run(rt,&s[i],&snap))goto done;copy=snap;if(!copy.valid||copy.normalized_result!=PST_RESULT_AUTH_FAILURE||strcmp(copy.backend_id,"schannel"))goto done;memset(&inf,0,sizeof(inf));inf.struct_size=sizeof(inf);inf.api_version=PST_API_VERSION;if(pst_runtime_get_info(rt,&inf)!=PST_RESULT_OK||inf.capabilities!=0x00000e7dUL)goto done;ok=creates==4&&destroys==4&&setups==3&&cleanups==3&&keys()==0;printf("ISOLATION_CLEANUP CONNECTION_CREATE=%d CONNECTION_DESTROY=%d IDENTITY_SETUP=%d IDENTITY_CLEANUP=%d C_SNAPSHOT_IMMUTABLE=1 PST_MTLS_KEY_REMAINS=%d CAPABILITIES=0x%08lx\n",creates,destroys,setups,cleanups,keys(),(unsigned long)inf.capabilities);
